1196	\begin{lemma}[Combined line measurement on the extended coordinates]
1197		\label{lem:qld-4-13}
1198		\lean{MIPStarRE.QPBT.ExtendedLinesWitness}
1199		\lean{MIPStarRE.QPBT.exists_extendedLinesWitness}
1200		\notready
1201		\uses{lem:qld-4-12, def:line, def:line-point-dist, def:consistency,
1202			def:bracket, def:expanded-state, def:ideg-deg-polynomials}
1203		% Statement as in the source (references/qpbt-paper/
1204		% 14_analysis_of_the_pauli_basis_test.tex, lem:qld-4-13), including the
1205		% error form poly(m^2 eps, md/q); neither of the source's two proof
1206		% routes delivers that form, and the route retained below establishes
1207		% m * poly(eps, md/q), which is the form the sequel uses. See
1208		% rem:qld-4-13-source-defects and the analysis in
1209		% docs/paper-gaps/qpbt_combined-lines-error-term.tex. The line-point
1210		% distribution over F_q^{2m+2} presupposes that 2m+2 divides q; see
1211		% rem:qld-4-7-divisibility.
1212		There exists a function
1213		$\delta_{\mathrm{combine}}(\eps,m,d,q) = \poly(m^2\eps, md/q)$, the
1214		two-variable polynomial error read in the corrected sum sense of
1215		\cite{gap:qpbt_pasting-product-error}, that is, a bound
1216		$C\bigl((m^2\eps)^{r} + (md/q)^{s}\bigr)$ with $C \ge 1$ and $r, s > 0$ on
1217		the closed nonnegative quadrant rather than the literal product form of the
1218		shorthand, such that the following holds. For
1219		every line $\ell$ in $\F_q^{2m+2}$ and
1220		$\hilb \in \{\hilb_{\mathsf{A}}, \hilb_{\mathsf{B}}\}$ there exists a
1221		POVM $\{\hat{Q}^{\ell}_{f}\}$ acting on $\hilb \ot (\C^q)^{\ot M}$ with
1222		outcomes $f \in \deg_{md+1}(\ell)$ such that on average over a uniformly
1223		random pair $(\ell, (x,z,\alpha,\beta))$ drawn from the line-point
1224		distribution over $\F_q^{2m+2}$,
1225		\begin{gather}
1226			\label{eq:qld-4-13}
1227			\big(\hat{Q}^{\ell}
1228			_{[\mathrm{eval}_{(x,z,\alpha,\beta)}(\cdot)=a]}
1229			\big)_{\mathsf{A}\mathsf{A}'}
1230			\simeq_{\delta_{\mathrm{combine}}}
1231			\big(\hat{Q}^{x,z,\alpha,\beta}_{a}\big)_{\mathsf{B}\mathsf{A}''}\,,
1232			\\
1233			\big(\hat{Q}^{\ell}
1234			_{[\mathrm{eval}_{(x,z,\alpha,\beta)}(\cdot)=a]}
1235			\big)_{\mathsf{B}\mathsf{B}'}
1236			\simeq_{\delta_{\mathrm{combine}}}
1237			\big(\hat{Q}^{x,z,\alpha,\beta}_{a}\big)_{\mathsf{A}\mathsf{B}''}\,,
1238			\notag
1239		\end{gather}
1240		where the answer summation is over $a \in \F_q$. Moreover, if $\ell$ is
1241		axis-parallel, then the outcome $f \in \deg_{d}(\ell)$.
1242	\end{lemma}
1243	
1244	Before proving the lemma we record definitions and estimates concerning
1245	distributions over lines and points. Recall from
1246	Definition~\ref{def:line-point-dist} that the line-point distribution over
1247	$\F_q^m$ is an even mixture of an axis-parallel component $D_{\mathrm{ALine}}$
1248	and a diagonal component $D_{\mathrm{DLine}}$.
1249	
1250	\begin{definition}[Restricted line distributions]
1251		\label{def:ith-restricted-line}
1252		\lean{MIPStarRE.QPBT.restrictedALineDist, MIPStarRE.QPBT.restrictedDLineDist}
1253		\lean{MIPStarRE.QPBT.restrictedALineDist_isProbability}
1254		\lean{MIPStarRE.QPBT.restrictedDLineDist_isProbability}
1255		\leanok
1256		\uses{def:line-point-dist, def:ld-question-distribution}
1257		Use coordinate indices $i\in\{0,\dots,m-1\}$ throughout this definition,
1258		the following mixture estimates, and the sub-line construction below. Write
1259		$\bar\chi(s)=\chi(s)-1$, where $\chi$ is the one-based index function of
1260		Definition~\ref{def:ld-question-distribution}. Thus $\bar\chi$ takes
1261		values in $\{0,\dots,m-1\}$, and index $i$ here denotes coordinate $i+1$
1262		in the one-based notation of \cite{Ji2020MIPStar}.
1263		For any such $i$, the \emph{$i$-th restricted
1264		axis-parallel line distribution} $D_{\mathrm{ALine},i}$ is the
1265		restriction of $D_{\mathrm{ALine}}$ to pairs $(\ell, u)$ where the line
1266		$\ell$ is along the direction $e_i$, i.e.\ is of the form
1267		$\ell = (u_0, e_i)$. Similarly, the \emph{$i$-th restricted diagonal line
1268		distribution} $D_{\mathrm{DLine},i}$ is the restriction of
